import inspect
import json
import os
from pathlib import Path

import pytest

import settings.cache as cache_module
from settings.cache import load_settings


def write_fixed(path, payload, stamp_ns):
    path.write_text(payload, encoding="utf-8")
    os.utime(path, ns=(stamp_ns, stamp_ns))


def freeze_all_stat_identity(monkeypatch, path):
    target = os.path.abspath(os.fspath(path))
    real_os_stat = os.stat
    frozen = real_os_stat(path)

    def is_target(candidate):
        try:
            return os.path.abspath(os.fspath(candidate)) == target
        except TypeError:
            return False

    def fake_stat(candidate, *args, **kwargs):
        if is_target(candidate):
            return frozen
        return real_os_stat(candidate, *args, **kwargs)

    real_path_stat = Path.stat

    def fake_path_stat(candidate, *args, **kwargs):
        if is_target(candidate):
            return frozen
        return real_path_stat(candidate, *args, **kwargs)

    monkeypatch.setattr(os, "stat", fake_stat)
    monkeypatch.setattr(Path, "stat", fake_path_stat)

    stat_alias = getattr(cache_module, "stat", None)
    if callable(stat_alias):
        monkeypatch.setattr(cache_module, "stat", fake_stat)
    lstat_alias = getattr(cache_module, "lstat", None)
    if callable(lstat_alias):
        monkeypatch.setattr(cache_module, "lstat", fake_stat)

    metadata = {
        "getctime": frozen.st_ctime,
        "getmtime": frozen.st_mtime,
        "getsize": frozen.st_size,
    }
    for name, fixed_value in metadata.items():
        real_getter = getattr(os.path, name)

        def fake_getter(candidate, _real=real_getter, _value=fixed_value):
            return _value if is_target(candidate) else _real(candidate)

        monkeypatch.setattr(os.path, name, fake_getter)
        if callable(getattr(cache_module, name, None)):
            monkeypatch.setattr(cache_module, name, fake_getter)


def test_same_size_same_mtime_rewrite_is_fresh(tmp_path):
    path = tmp_path / "settings.json"
    stamp = 1_700_000_000_000_000_000
    first = json.dumps({"name": "Ada", "mode": 1})
    second = json.dumps({"name": "Eve", "mode": 2})
    assert len(first.encode()) == len(second.encode())
    write_fixed(path, first, stamp)
    assert load_settings(path)["name"] == "Ada"
    write_fixed(path, second, stamp)
    assert load_settings(path) == {"name": "Eve", "mode": 2}


def test_freshness_does_not_depend_on_ctime_inode_or_any_stat_identity(tmp_path, monkeypatch):
    path = tmp_path / "settings.json"
    first = json.dumps({"name": "Ada", "mode": 1})
    second = json.dumps({"name": "Eve", "mode": 2})
    path.write_text(first, encoding="utf-8")
    assert load_settings(path)["name"] == "Ada"
    freeze_all_stat_identity(monkeypatch, path)
    path.write_text(second, encoding="utf-8")
    assert load_settings(path) == {"name": "Eve", "mode": 2}


def test_delete_and_recreate_same_path_does_not_resurrect_old_content(tmp_path):
    path = tmp_path / "settings.json"
    stamp = 1_700_000_000_000_000_000
    write_fixed(path, '{"name": "old"}', stamp)
    assert load_settings(path)["name"] == "old"
    path.unlink()
    write_fixed(path, '{"name": "new"}', stamp)
    assert load_settings(path)["name"] == "new"


def test_invalid_replacement_is_not_hidden_by_stale_cache(tmp_path):
    path = tmp_path / "settings.json"
    stamp = 1_700_000_000_000_000_000
    write_fixed(path, '{"name": "Ada"}', stamp)
    assert load_settings(path)["name"] == "Ada"
    write_fixed(path, '{"name":', stamp)
    with pytest.raises(json.JSONDecodeError):
        load_settings(path)


def test_public_signature_is_unchanged():
    assert list(inspect.signature(load_settings).parameters) == ["path"]
